import {mountApplicationShell} from '../forge-shell/shell.mjs';
import {deploymentPath} from '../deployment.mjs';
export function mountForgeShell({doc,root,onMode,getCircuit,getProject,bridge,onLocalSave}={}){
 const help=doc.createElement('div');const $=s=>doc.querySelector(s)||help.querySelector(s),make=(tag,text)=>{const n=doc.createElement(tag);if(text)n.textContent=text;return n;};
 const oldBrowser=$('.forge-controls'),props=$('.forge-inspector'),form=$('#forge-controls'),bench=$('.forge-workbench'),physical=$('#forge-mode-physical'),signal=$('#forge-response-lab'),workflow=$('#forge-workflow'),parts=$('#forge-logical-parts'),local=$('.local-projects');
 help.append($('.forge-heading'),workflow);for(const n of [...root.querySelectorAll('.category-learning,.forge-back')])help.append(n);const learning=[...root.children].find(n=>n.tagName==='DETAILS');if(learning)help.append(learning);
 const design=make('div');design.className='forge-browser-configuration';design.append($('#forge-circuit-state'),form);for(const n of [...oldBrowser.children])help.append(n);oldBrowser.remove();
 const propertyTitle=$('#forge-inspector-title');propertyTitle.textContent='Inspector';const section=$('#forge-inspection').closest('section'),overview=make('details'),overviewTitle=make('summary','Circuit overview');overview.open=true;overview.className='forge-inspector-overview';section.before(overview);overview.append(overviewTitle,section);
 const limitations=make('details'),limitTitle=make('summary','Model limitations');limitations.className='forge-model-limitations';limitations.append(limitTitle,$('.forge-inspector>.forge-limit'));props.append(limitations);
 const status=make('div');status.append($('#forge-status'),$('#forge-workbench-identity'));for(const id of ['forge-import-note','forge-capability-status','forge-instrument-limit'])if($('#'+id))status.append($('#'+id));const source=$('.forge-source-context');if(source)help.append(source);const contextMenu=$('.forge-context-actions');if(contextMenu)help.append(contextMenu);help.append($('.forge-workbench-heading'));
 const diagrams=$('.forge-workspace-modes');diagrams.hidden=true;help.append(diagrams);
 const editActions=make('div');editActions.className='forge-edit-actions';editActions.setAttribute('role','group');editActions.setAttribute('aria-label','Circuit editing history');editActions.append($('#forge-undo'),$('#forge-redo'));physical.querySelector('.forge-presentation-modes').append(editActions);physical.querySelector('[data-forge-presentation="build"]').textContent='Assembly view';
 const buildActions=make('nav');buildActions.className='forge-build-actions';buildActions.setAttribute('aria-label','Build tools and exports');for(const id of ['forge-view-wiring','forge-guided-build','forge-kit','forge-design-bleed'])buildActions.append($('#'+id));parts.prepend(buildActions);
 const exportAction=make('button','Wiring SVG / Print');exportAction.type='button';exportAction.addEventListener('click',()=>{const link=$('#forge-view-wiring');if(!link.hidden)link.click();});exportAction.setAttribute('aria-description','Open the existing Wiring Diagram Generator to export supported wiring.');buildActions.append(exportAction);exportAction.disabled=$('#forge-view-wiring').hidden;
 const commands=[];let shell,saved=null;
 function showInspection(selection){propertyTitle.textContent=selection?'Inspector / Selection':'Inspector';overviewTitle.textContent=selection?'Selection and connections':'Circuit overview';overview.open=true;shell?.setSelection(selection);}
 const context=bridge?.context;shell=mountApplicationShell(root,{id:'forge-design',context:{kind:context?'project':'local',title:context?.title||'Local design',revision:context?.revision||'',save:context?'Editor design · cloud save is explicit':'Unsaved local design'},views:[{id:'circuit',title:'Circuit',node:physical},{id:'signal',title:'Signal',node:signal},{id:'build',title:'Build / Parts',node:parts},{id:'local',title:'Local Save / Share',node:local}],commands,browser:[],browserContent:design,panelLabels:{properties:'Inspector'},properties:props,status,help,links:[{text:'Projects',href:deploymentPath('/circuit-forge/projects/')},{text:'Account',href:deploymentPath('/account/')}],drawers:{browser:$('#forge-configure-sheet'),properties:$('#forge-inspector-sheet')},onView:id=>{if(id==='circuit')onMode('physical',true);if(id==='signal')onMode('signal',true);}});
 shell.browser.classList.add('forge-controls');shell.browser.querySelector('h2').textContent='Configuration';shell.workspace.classList.add('forge-workbench');help.append(...bench.children);bench.remove();$('.forge-mobile-toolbar')?.setAttribute('hidden','');showInspection(null);
 for(const g of form.querySelectorAll('[data-configure-group]')){g.hidden=false;g.open=g.dataset.configureGroup==='guitar';g.addEventListener('toggle',()=>{if(g.open)for(const other of form.querySelectorAll('[data-configure-group]'))if(other!==g)other.open=false;});}
 const localDetails=local.querySelector('details');localDetails.open=true;const save=[...local.querySelectorAll('button')].find(n=>n.textContent==='Save current');if(save){save.textContent='Save locally';shell.appbar.append(save);save.addEventListener('click',()=>queueMicrotask(()=>{const message=local.querySelector('[role="status"]')?.textContent;if(message==='Project saved on this browser.'){saved=JSON.stringify(getCircuit().state);shell.setContext({save:'Saved locally on this browser'});onLocalSave?.();}else shell.setContext({save:'Local save failed · design retained'});}));}
 if(bridge?.send)bridge.send.textContent=context?'Send for cloud revision':'Send design to Projects';
 return Object.assign(shell,{showInspection(selection,{open=false}={}){showInspection(selection);if(open)shell.openPanel('properties',{focus:false});},update(){exportAction.disabled=$('#forge-view-wiring').hidden;exportAction.title=exportAction.disabled?'Wiring export is unavailable for this circuit':'Open Wiring Generator export';if(!context){const title=getProject()?.name||'Local design';shell.setContext({title,save:saved?(saved===JSON.stringify(getCircuit().state)?'Saved locally on this browser':'Unsaved changes · local design'):'Unsaved local design'});}else shell.setContext({save:'Editor design · send for explicit cloud revision'});},modeChanged(mode){shell.selectView(mode==='signal'?'signal':'circuit');}});
}
